    private static AWSEventsClientConfig WithEndpoint(Uri endpoint, AWSEventsClientConfig? config)
    {
        ArgumentNullException.ThrowIfNull(endpoint);
        var copy = config is null ? new AWSEventsClientConfig() : new AWSEventsClientConfig(config);
        copy.Endpoint = endpoint;
        return copy;
    }

